import os,re
from pathlib import Path
# replicate host detection from script
MEMORY_ROOT=Path.home()/'.dc-platform'/'memory'
def _host_id():
  env=(os.environ.get('WORKLOG_HOST_ID') or '').strip()
  if env: return env
  for p in [Path.home()/'.zshrc', Path.home()/'.zprofile', Path.home()/'.bashrc', MEMORY_ROOT/'work-log'/'HOST_ID']:
    if not p.exists(): continue
    for line in p.read_text(errors='replace').splitlines():
      if line.startswith('export WORKLOG_HOST_ID='):
        return line.split('=',1)[1].strip().strip("'\"")
      if line.startswith('WORKLOG_HOST_ID='):
        return line.split('=',1)[1].strip().strip("'\"")
  # fallback?
  return 'unknown'
print('host', _host_id())
auth=Path(MEMORY_ROOT/'work-log'/'AUTHORITY_HOST')
print('auth file', auth.read_text().strip() if auth.exists() else 'MISS')
# check launchd for daily report
import subprocess
r=subprocess.run(['launchctl','list'],capture_output=True,text=True)
for line in r.stdout.splitlines():
  if 'daily-report' in line or 'youchu' in line.lower():
    if 'daily' in line or 'report' in line: print(line)
